-- Isolated SQL fixtures; no real HTTP authentication is claimed.
BEGIN;
GRANT USAGE ON SCHEMA community_test TO service_role;
GRANT SELECT ON community_test.ids TO service_role;
CREATE TEMP TABLE objective_baseline AS SELECT community_test.snapshot() value;
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT public.save_server_community(community_test.id('a'),community_test.payload('a'),0);
SELECT community_test.assert((public.get_community_objectives(community_test.id('a'))->>'verifier_enabled')='false','missions default unavailable');
SELECT community_test.assert(public.get_community_objectives(community_test.id('a'))#>>'{missions,0,status}'='unavailable','future mission is explicit');
SELECT community_test.assert(jsonb_array_length(public.get_community_objectives(community_test.id('a'))->'recent_achievements')=1,'new activation unlocks one cosmetic-free milestone');
SELECT public.disable_server_community(community_test.id('a'),1);
SELECT public.save_server_community(community_test.id('a'),community_test.payload('a'),2);
SELECT community_test.assert(jsonb_array_length(public.get_community_objectives(community_test.id('a'))->'recent_achievements')=1,'toggles never repeat activation unlock');
CREATE TEMP TABLE objective_directory_payload AS SELECT jsonb_build_object('name','Comunidade local','description','Descrição sintética para teste local.', 'icon_url',NULL,'banner_url',NULL,'category','gaming','language','pt-br','interests','["coop"]'::jsonb,'public_rules','["Respeito."]'::jsonb,'admission','approval','consent',true) value;
SELECT public.save_community_discovery(community_test.id('a'),(SELECT value FROM objective_directory_payload),0,true);
SELECT public.save_community_discovery(community_test.id('a'),(SELECT value FROM objective_directory_payload),1,false);
SELECT public.save_community_discovery(community_test.id('a'),(SELECT value FROM objective_directory_payload),2,true);
SELECT community_test.assert(jsonb_array_length(public.list_community_achievements(community_test.id('a')))=2,'gallery projects real catalog');
SELECT community_test.assert(jsonb_array_length(public.get_community_objectives(community_test.id('a'))->'recent_achievements')=2,'first publication counted once');
SELECT community_test.denied($q$INSERT INTO public.community_achievement_unlocks(server_id,objective_id,version) VALUES(community_test.id('a'),'community_publication',1)$q$,'42501');
SELECT community_test.denied($q$UPDATE public.community_objective_versions SET target=1$q$,'42501');
SELECT community_test.denied('SELECT * FROM public.community_reward_unlocks','42501');
SELECT community_test.denied($q$SELECT public.consume_verified_community_activity(community_test.id('a'),gen_random_uuid())$q$,'42501');
SELECT community_test.denied($q$SELECT public.list_community_achievements(community_test.id('a'),'',51)$q$,'22023');
SELECT community_test.assert(jsonb_array_length(public.list_community_achievements(community_test.id('a'),'community_foundation',1))=1,'gallery cursor exclusive');
SELECT community_test.actor(5);
SELECT community_test.assert(public.get_community_objectives(community_test.id('a'))#>>'{missions,0,progress}'='0','ordinary member reads but cannot score');
SELECT community_test.actor(7);
SELECT community_test.denied($q$SELECT public.get_community_objectives(community_test.id('a'))$q$,'42501');
RESET ROLE;
SELECT community_test.assert(NOT EXISTS(SELECT FROM public.community_xp_accounts),'administrative achievements give no XP');
SELECT community_test.assert(NOT EXISTS(SELECT FROM public.community_reward_catalog r WHERE r.usable AND NOT EXISTS(SELECT FROM security_private.community_cosmetic_assets a WHERE a.reward_id=r.id)),'4C usable cosmetics have implemented render bindings, no fictional usable assets');
UPDATE security_private.community_xp_policy SET enabled=true,daily_cap=450,weekly_cap=450;
INSERT INTO security_private.community_verified_activities(id,server_id,source,evidence_key,expires_at)
SELECT ('d4b10000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,community_test.id('a'),'backend_verified_activity',gen_random_uuid(),clock_timestamp()+interval '1 hour' FROM generate_series(1,12)n;
-- A real 4A attestation does not progress a mission with the verifier disabled.
SELECT public.consume_verified_community_activity(community_test.id('a'),'d4b10000-0000-0000-0000-000000000001');
SELECT community_test.assert(NOT EXISTS(SELECT FROM public.community_mission_progress),'no progression without explicit verifier activation');
INSERT INTO public.community_reward_catalog VALUES('test_community_seal','seal','Selo de teste','Contrato sintético, sem ativo visual.',false);
INSERT INTO public.community_objective_versions(objective_id,version,name,description,target,category,rarity,reward_xp,reward_id) VALUES('verified_daily',2,'Diária local','Fixture verificada, não publicar.',3,'participation','common',150,'test_community_seal');
UPDATE security_private.community_objective_active SET version=2 WHERE objective_id='verified_daily';
UPDATE security_private.community_objective_verifiers SET enabled=true,changed_at=clock_timestamp();
SELECT public.consume_verified_community_activity(community_test.id('a'),'d4b10000-0000-0000-0000-000000000002');
SELECT community_test.assert((SELECT progress=1 AND version=2 FROM public.community_mission_progress WHERE objective_id='verified_daily'),'mission pins current version');
INSERT INTO public.community_objective_versions(objective_id,version,name,description,target,category,rarity,reward_xp) VALUES('verified_daily',3,'Nova diária','Não deve alterar a missão iniciada.',1,'participation','rare',9999);
UPDATE security_private.community_objective_active SET version=3 WHERE objective_id='verified_daily';
SELECT public.consume_verified_community_activity(community_test.id('a'),'d4b10000-0000-0000-0000-000000000003');
SELECT community_test.assert((SELECT progress=2 AND version=2 AND completed_at IS NULL FROM public.community_mission_progress WHERE objective_id='verified_daily'),'changed criteria do not complete pinned mission');
SET LOCAL ROLE service_role;
RESET ROLE;
SAVEPOINT mission_atomicity;
CREATE FUNCTION community_test.fail_mission_reward() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT FROM security_private.community_verified_activities WHERE id=NEW.activity_id AND source='community_mission_reward') THEN RAISE EXCEPTION 'test_mission_reward_failure'; END IF; RETURN NEW; END $$;
CREATE TRIGGER fail_mission_reward BEFORE INSERT ON public.community_xp_ledger FOR EACH ROW EXECUTE FUNCTION community_test.fail_mission_reward();
SELECT community_test.denied($q$SELECT public.consume_verified_community_activity(community_test.id('a'),'d4b10000-0000-0000-0000-000000000004')$q$,'P0001','test_mission_reward_failure');
SELECT community_test.assert((SELECT progress=2 AND completed_at IS NULL FROM public.community_mission_progress WHERE objective_id='verified_daily'),'reward failure rolls back mission completion');
SELECT community_test.assert((SELECT xp=300 FROM public.community_xp_accounts),'reward failure rolls back original XP as well');
SELECT community_test.assert(NOT EXISTS(SELECT FROM public.community_reward_unlocks WHERE reward_id='test_community_seal'),'reward failure rolls back synthetic cosmetic contract');
ROLLBACK TO SAVEPOINT mission_atomicity;
SET LOCAL ROLE service_role;
SELECT public.consume_verified_community_activity(community_test.id('a'),'d4b10000-0000-0000-0000-000000000004');
RESET ROLE;
SELECT community_test.assert((SELECT progress=3 AND version=2 AND completed_at IS NOT NULL FROM public.community_mission_progress WHERE objective_id='verified_daily'),'trusted backend completes mission');
SELECT community_test.assert((SELECT count(*)=1 FROM public.community_reward_unlocks WHERE reward_id='test_community_seal'),'one synthetic community cosmetic contract unlocked');
SELECT community_test.assert((SELECT NOT usable FROM public.community_reward_catalog WHERE id='test_community_seal'),'synthetic unlock is not advertised usable');
SELECT community_test.assert((SELECT xp=450 FROM public.community_xp_accounts),'same 4A wallet and cap, including mission reward');
SELECT community_test.assert((SELECT l.requested_xp=150 AND l.awarded_xp=50 FROM public.community_mission_progress m JOIN public.community_xp_ledger l ON l.activity_id=m.reward_activity_id WHERE m.objective_id='verified_daily'),'mission reward is partially capped even with service role');
SELECT community_test.assert((SELECT progress=3 FROM public.community_mission_progress WHERE objective_id='verified_weekly'),'reward event never recursively counts as activity');
SELECT public.consume_verified_community_activity(community_test.id('a'),'d4b10000-0000-0000-0000-000000000004');
SELECT community_test.assert((SELECT progress=3 FROM public.community_mission_progress WHERE objective_id='verified_weekly'),'attestation replay does not advance missions');
SELECT public.consume_verified_community_activity(community_test.id('a'),('d4b10000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid) FROM generate_series(5,11)n;
SELECT community_test.assert((SELECT count(*)=2 FROM public.community_mission_progress WHERE completed_at IS NOT NULL),'daily and weekly complete once');
SELECT community_test.assert((SELECT count(*)=3 FROM security_private.community_mission_evidence e JOIN public.community_mission_progress m ON m.id=e.mission_id WHERE m.objective_id='verified_daily'),'daily audit identifies the exact three credited attestations');
SELECT community_test.assert((SELECT count(*)=10 FROM security_private.community_mission_evidence e JOIN public.community_mission_progress m ON m.id=e.mission_id WHERE m.objective_id='verified_weekly'),'weekly audit identifies exact evidence without counting reward events');
SELECT community_test.denied($q$DELETE FROM security_private.community_mission_evidence$q$,'23514','community_objective_immutable');
SELECT community_test.assert((SELECT count(*)=2 FROM public.community_xp_ledger l JOIN security_private.community_verified_activities f ON f.id=l.activity_id WHERE f.source='community_mission_reward'),'one reward ledger per completed period');
SELECT community_test.assert((SELECT xp=450 FROM public.community_xp_accounts),'weekly reward shares the same cap');
SELECT community_test.assert((SELECT l.awarded_xp=0 FROM public.community_mission_progress m JOIN public.community_xp_ledger l ON l.activity_id=m.reward_activity_id WHERE m.objective_id='verified_weekly'),'weekly reward is terminal zero under exhausted cap');
SELECT community_test.denied($q$UPDATE public.community_objective_versions SET target=100$q$,'23514','community_objective_immutable');
SELECT community_test.denied($q$UPDATE public.community_objective_keys SET criterion='first_publication' WHERE id='community_foundation'$q$,'23514','community_objective_immutable');
SELECT community_test.denied($q$UPDATE public.community_mission_progress SET progress=0$q$,'23514');
SELECT community_test.denied($q$DELETE FROM public.community_achievement_unlocks$q$,'23514','community_objective_immutable');
SELECT community_test.denied($q$INSERT INTO public.community_objective_versions(objective_id,version,name,description,target,category,rarity,reward_xp) VALUES('community_foundation',2,'Abuso','Não permitir.',1,'foundation','common',10)$q$,'23514','community_achievement_no_xp');
INSERT INTO security_private.community_verified_activities VALUES('d4b20000-0000-0000-0000-000000000001',community_test.id('a'),'community_mission_reward',gen_random_uuid(),clock_timestamp(),clock_timestamp()+interval '1 hour');
SELECT community_test.denied($q$SELECT public.consume_verified_community_activity(community_test.id('a'),'d4b20000-0000-0000-0000-000000000001')$q$,'22023','community_reward_unbound');
SELECT community_test.actor(1);
SELECT community_test.assert(jsonb_array_length(public.list_community_mission_history(community_test.id('a')))=2,'completion history RPC');
SELECT community_test.assert(public.list_community_mission_history(community_test.id('a'))#>>'{0,status}'='completed','history status');
SELECT community_test.assert(NOT(public.get_community_objectives(community_test.id('a'))#>'{missions,0}' ? 'reward_activity_id'),'no private evidence exposed');
-- Expired records remain visible without fabricating an objective for every past day.
INSERT INTO public.community_mission_progress(server_id,objective_id,version,period_start,expires_at,progress)
VALUES(community_test.id('a'),'verified_daily',2,clock_timestamp()-interval '3 days',clock_timestamp()-interval '2 days',1);
SELECT community_test.assert(public.list_community_mission_history(community_test.id('a'))#>>'{0,status}'='expired','incomplete past instance expires');
SELECT community_test.assert(jsonb_array_length(public.list_community_mission_history(community_test.id('a'),(public.list_community_mission_history(community_test.id('a'),NULL,1)#>>'{0,id}')::bigint,2))=2,'history cursor excludes first row');
GRANT SELECT ON public.community_achievement_unlocks,public.community_mission_progress TO authenticated;
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT community_test.assert(NOT EXISTS(SELECT FROM public.community_achievement_unlocks),'RLS denies raw unlock rows even after grant');
SELECT community_test.assert(NOT EXISTS(SELECT FROM public.community_mission_progress),'RLS denies raw progress rows even after grant');
SELECT public.disable_server_community(community_test.id('a'),3);
SELECT community_test.denied($q$SELECT public.get_community_objectives(community_test.id('a'))$q$,'42501');
SELECT public.save_server_community(community_test.id('a'),community_test.payload('a'),4);
SELECT community_test.assert(jsonb_array_length(public.get_community_objectives(community_test.id('a'))->'recent_achievements')=2,'disable and reactivation preserve unlocks');
SELECT community_test.assert(jsonb_array_length(public.list_community_mission_history(community_test.id('a')))=3,'disable preserves mission history');
RESET ROLE;
SAVEPOINT catalog_capacity;
INSERT INTO public.community_objective_keys SELECT 'test_daily_'||n,'mission','verified_activity','daily' FROM generate_series(1,8)n;
INSERT INTO public.community_objective_versions(objective_id,version,name,description,target,category,rarity) SELECT 'test_daily_'||n,1,'Teste de limite','Fixture sintética de catálogo.',5,'participation','common' FROM generate_series(1,8)n;
INSERT INTO security_private.community_objective_active SELECT 'test_daily_'||n,1 FROM generate_series(1,7)n;
SELECT community_test.denied($q$INSERT INTO security_private.community_objective_active VALUES('test_daily_8',1)$q$,'23514','community_mission_catalog_limit');
ROLLBACK TO SAVEPOINT catalog_capacity;
SELECT community_test.assert((community_test.snapshot()->'xp')=(SELECT value->'xp' FROM objective_baseline),'individual XP unchanged');
SELECT community_test.assert((community_test.snapshot()->'badges')=(SELECT value->'badges' FROM objective_baseline),'individual badges unchanged');
SELECT community_test.assert((community_test.snapshot()->'messages')=(SELECT value->'messages' FROM objective_baseline),'messages unchanged');
ROLLBACK;
